#!/bin/bash
# MNIST, MLP 784-32-32-10 + LayerNorm, arm=diag (WCT reference arm). Writes to benchmarks/outputs/mlp_ln_mnist/diag/.
# Generated by benchmarks/slurm/generate_jobs.py — edit that file, not this one.
# See docs/reports/plan_exp_step1.md §6 and benchmarks/slurm/README.md.
# Submit from the repository root:  sbatch benchmarks/slurm/train_mlp_ln_mnist_diag.sh

#SBATCH --account=def-msh-ab
#SBATCH --job-name=mlp_ln_mnist_diag
#SBATCH --gpus=h100_1g.10gb:1
#SBATCH --cpus-per-task=8
#SBATCH --mem=16G
#SBATCH --time=00:20:00
#SBATCH --output=benchmarks/slurm/logs/%x-%j.out

# --time: MEASURED. Worst arm tekfac at 2.02 ms/step; 429 steps/epoch x 20 epochs = 8 580 steps -> ~17 s of training. Setup-dominated.
# Dataset: mnist must be staged under $SLURM_SUBMIT_DIR/dataset (compute nodes have no
# internet; --no-allow-download turns a missing dataset into a clear error, not a timeout).

set -euo pipefail
cd "$SLURM_SUBMIT_DIR"

module purge
module load StdEnv/2023 gcc/13.3 cuda/12.6 python/3.11.5

virtualenv --no-download "$SLURM_TMPDIR/env"
source "$SLURM_TMPDIR/env/bin/activate"
pip install --no-index --upgrade pip
pip install --no-index -r requirements-cluster.txt

export PYTHONPATH="$SLURM_SUBMIT_DIR/src:$SLURM_SUBMIT_DIR"

# Reference arm (plan_lot8.md §0.7): a fixed 20-epoch run whose measured elapsed time is
# every other arm's wall-clock budget. Read it back from the run's manifest.json:
#   python -c "import json;print(json.load(open('benchmarks/outputs/mlp_ln_mnist/diag/manifest.json'))['arms']['diag']['total_s'])"
# and pass it to the other jobs as --wct-budget (they default to WCT_BUDGET below).
python -m benchmarks.mlp_ln_mnist.bench \
  --arms diag \
  --epochs 20 \
  --budget-mode epochs \
  --num-workers 8 \
  --no-allow-download \
  --data-root "$SLURM_SUBMIT_DIR/dataset" \
  --checkpoints 0,0.01,0.1,0.5,1 \
  --output-dir "$SLURM_SUBMIT_DIR/benchmarks/outputs/mlp_ln_mnist/diag"
